$ErrorActionPreference='SilentlyContinue'; $s = New-Object -ComObject Microsoft.Update.Session; $searcher = $s.CreateUpdateSearcher(); $res = $searcher.Search("__CRITERIA__"); if ($null -eq $res -or $res.Updates.Count -eq 0) {   [pscustomobject]@{ Count = 0; Installed = 0; Titles = @() } | ConvertTo-Json -Compress; exit 0 } $titles = @($res.Updates | ForEach-Object { [string]$_.Title }); $toDownload = New-Object -ComObject Microsoft.Update.UpdateColl; foreach ($u in $res.Updates) { if (-not $u.EulaAccepted) { $u.AcceptEula() }; [void]$toDownload.Add($u) }; $dl = $s.CreateUpdateDownloader(); $dl.Updates = $toDownload; $dlRes = $dl.Download(); $toInstall = New-Object -ComObject Microsoft.Update.UpdateColl; foreach ($u in $res.Updates) { if ($u.IsDownloaded) { [void]$toInstall.Add($u) } }; $installed = 0; $installResult = -1; if ($toInstall.Count -gt 0) {   $inst = $s.CreateUpdateInstaller(); $inst.Updates = $toInstall; $instRes = $inst.Install();   $installResult = [int]$instRes.ResultCode;   if ($installResult -eq 2 -or $installResult -eq 3) { $installed = $toInstall.Count } } else {   Start-Process 'UsoClient.exe' -ArgumentList 'StartInteractiveScan' -WindowStyle Hidden -ErrorAction SilentlyContinue } [pscustomobject]@{ Count = $titles.Count; Installed = $installed; InstallResult = $installResult; Titles = $titles } | ConvertTo-Json -Compress